CREATE POLICY partner_logos_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'partner-logos' AND (public.is_admin(auth.uid()) OR EXISTS (SELECT 1 FROM public.partners p WHERE p.id::text = (storage.foldername(name))[1] AND p.user_id = auth.uid())));
CREATE POLICY partner_logos_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'partner-logos' AND (storage.extension(name)) IN ('jpg', 'jpeg', 'png') AND EXISTS (SELECT 1 FROM public.partners p WHERE p.id::text = (storage.foldername(name))[1] AND p.user_id = auth.uid()));
CREATE POLICY partner_logos_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'partner-logos' AND (public.is_admin(auth.uid()) OR EXISTS (SELECT 1 FROM public.partners p WHERE p.id::text = (storage.foldername(name))[1] AND p.user_id = auth.uid())));